{
  "name": "opencode-opendeck",
  "version": "0.2.0",
  "type": "module",
  "description": "Live mission-control dashboard for the OpenCode v2 TUI: context gauge, live agent tree, approvals, git and files-by-agent, diff, usage.",
  "author": "opencode-opendeck contributors",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ptthien1012/opencode-opendeck.git"
  },
  "homepage": "https://github.com/ptthien1012/opencode-opendeck#readme",
  "bugs": {
    "url": "https://github.com/ptthien1012/opencode-opendeck/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "sidebar",
    "dashboard",
    "opendeck",
    "agents",
    "git",
    "diff",
    "usage"
  ],
  "engines": {
    "opencode": ">=2.0.0"
  },
  "exports": {
    "./tui": "./dist/index.js"
  },
  "files": [
    "dist",
    "tui.js"
  ],
  "scripts": {
    "bundle": "bun run script/build.mjs",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "check": "bun run typecheck && bun run test && bun run bundle"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.15",
    "solid-js": "^1.9.12",
    "@opentui/solid": "^0.5.1"
  },
  "peerDependencies": {
    "solid-js": ">=1.9.0",
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10"
  },
  "devDependencies": {
    "@opencode/client": "^2.0.15",
    "@opencode/theme": "2.2.0",
    "typescript": "^5.6.0"
  },
  "packageManager": "bun@1.3.14"
}
